import type { FilterForm } from 'models/Filters';

import type {
  PerformanceAndBreakdownDeepDiveViewBy,
  PerformanceAndBreakdownInnovationStageValue,
  PerformanceAndBreakdownWaterfallContextKey,
  PerformanceAndBreakdownWaterfallData,
} from '../../types';
import { applyInnovationStageToDeepDiveMock } from './applyInnovationStageToDeepDiveMock';
import { PerformanceAndBreakdownDeepDiveBrandWaterfallMock } from './deepDiveBrand';
import { PerformanceAndBreakdownDeepDiveBrandByCountryMap } from './deepDiveBrandByCountryMap';
import { PerformanceAndBreakdownDeepDiveCountryWaterfallMock } from './deepDiveCountry';
import {
  buildPerformanceAndBreakdownDeepDiveSkuMock,
  buildPerformanceAndBreakdownDeepDiveSkuTerminalMock,
} from './deepDiveSku';
import { buildPerformanceAndBreakdownDeepDiveSubBrandMock } from './deepDiveSubBrand';

export interface ResolveDeepDiveMockParams {
  activeViewBy: PerformanceAndBreakdownDeepDiveViewBy;
  contextKey: PerformanceAndBreakdownWaterfallContextKey;
  applied: FilterForm;
  innovationStage?: PerformanceAndBreakdownInnovationStageValue;
}

function resolveBrandByCountryMock(
  applied: FilterForm,
): PerformanceAndBreakdownWaterfallData {
  const countryCode = String(applied.country ?? 'BRA');

  return (
    PerformanceAndBreakdownDeepDiveBrandByCountryMap[countryCode] ??
    PerformanceAndBreakdownDeepDiveBrandByCountryMap.BRA
  );
}

function resolveSubBrandMock(
  applied: FilterForm,
): PerformanceAndBreakdownWaterfallData {
  return buildPerformanceAndBreakdownDeepDiveSubBrandMock(
    String(applied.brands),
  );
}

function resolveSkuMock(
  applied: FilterForm,
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
  activeViewBy: PerformanceAndBreakdownDeepDiveViewBy,
): PerformanceAndBreakdownWaterfallData {
  const brandName = String(applied.brands);
  const subBrandName = applied.sub_brands
    ? String(applied.sub_brands)
    : brandName;
  const baseMock = buildPerformanceAndBreakdownDeepDiveSkuMock({
    brandName,
    subBrandName,
  });

  if (contextKey === 'sku' || activeViewBy === 'sku') {
    return buildPerformanceAndBreakdownDeepDiveSkuTerminalMock(baseMock);
  }

  return baseMock;
}

function hasDrilledCountry(applied: FilterForm): boolean {
  const country = applied.country;
  return Boolean(country && country !== 'All' && country !== 'ABI');
}

export function resolveDeepDiveMock({
  activeViewBy,
  contextKey,
  applied,
  innovationStage,
}: ResolveDeepDiveMockParams): PerformanceAndBreakdownWaterfallData {
  let baseMock: PerformanceAndBreakdownWaterfallData;

  if (activeViewBy === 'country') {
    baseMock = PerformanceAndBreakdownDeepDiveCountryWaterfallMock;
  } else if (activeViewBy === 'brand') {
    if (contextKey === 'country' || hasDrilledCountry(applied)) {
      baseMock = resolveBrandByCountryMock(applied);
    } else {
      baseMock = PerformanceAndBreakdownDeepDiveBrandWaterfallMock;
    }
  } else if (activeViewBy === 'sub_brand') {
    baseMock = resolveSubBrandMock(applied);
  } else {
    baseMock = resolveSkuMock(applied, contextKey, activeViewBy);
  }

  if (!innovationStage) {
    return baseMock;
  }

  return applyInnovationStageToDeepDiveMock(baseMock, innovationStage);
}
